        5 => {
            var v: u32 = 0;
            for (0..4) |i| v |= @as(u32, raw.bytes[i]) << @intCast(8 * i);
            if (field.type == type_float) {
                const f: f32 = @bitCast(v);
                return .{ .float = f };
